class AgoFormatter {
  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return elapsedTime.format(-Math.floor(years), "year")
    if (months >= 1) return elapsedTime.format(-Math.floor(months), "month")
    if (weeks >= 1) return elapsedTime.format(-Math.floor(weeks), "week")
    if (days >= 1) return elapsedTime.format(-Math.floor(days), "day")
    if (hours >= 1) return elapsedTime.format(-Math.floor(hours), "hour")
    if (minutes >= 1) return elapsedTime.format(-Math.floor(minutes), "minute")

    return translate("just_now")
  }

}

class DaysAgoFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    return relativeDays(-days)
  }
}

class DaysAgoOrWeekdayFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter().format(date)
    } else {
      return new Intl.DateTimeFormat(locale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

class InDaysFormatter {
  format(date) {
    const days = differenceInDays(new Date(), date)

    return relativeDays(days)
  }
}

class TimeOrDateFormatter {
  format(date) {
    const days = differenceInDays(date, new Date())

    if (days >= 1) {
      return new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" }).format(date)
    } else {
      return new Intl.DateTimeFormat(locale, { timeStyle: "short" }).format(date)
    }
  }
}

function relativeDays(days) {
  if (Math.abs(days) <= 1) return styleableValue(relativeTime.format(days, "day"))
  return relativeTime.formatToParts(days, "day").map(({ type, value }) =>
    type === "integer" ? styleableValue(value) : value
  ).join("")
}

function styleableValue(value) {
  return `<span class="local-time-value">${value}</span>`
}
